jest.setTimeout(30000);
import React from 'react';
import renderer, { act } from 'react-test-renderer';
import {
  Chart,
  barPath,
  donutArcs,
  resolveChartProps,
} from '../../src/gen/components/chart';

/**
 * The chart engine's geometry and the spec it reads from a widget's props, and
 * every chart kind drawn with the options a design can set — the screens of one
 * app draw only the charts its design has.
 */
function draw(el: React.ReactElement): string {
  let tree!: renderer.ReactTestRenderer;
  act(() => {
    tree = renderer.create(el);
  });
  const json = JSON.stringify(tree.toJSON());
  act(() => tree.unmount());
  return json;
}

describe('the spec read from props', () => {
  it('several series, each with its own colour and stroke, the empty ones left out', () => {
    const spec = resolveChartProps({
      chartType: 'line',
      values: [1, 2, 3],
      series: [{ values: [1, 2, 3], color: '#f00', strokeWidth: 3 }, { values: [] }, 'bad', null, { values: [4, 5] }],
    });
    expect(spec.series).toEqual([
      { values: [1, 2, 3], color: '#f00', strokeWidth: 3 },
      { values: [4, 5], color: spec.strokeColor, strokeWidth: 2 },
    ]);
  });
  it('one series of the values when none is given, or none parses', () => {
    expect(resolveChartProps({ chartType: 'line', values: [1, 2] }).series).toHaveLength(1);
    expect(resolveChartProps({ chartType: 'line', values: [1, 2], series: [{ values: 'x' }] }).series).toHaveLength(1);
  });
  it('the legend sits right when there are labels, unless the design placed it', () => {
    expect(resolveChartProps({ chartType: 'donut', values: [1], labels: ['a'] }).legend).toBe('right');
    expect(resolveChartProps({ chartType: 'donut', values: [1] }).legend).toBe('none');
    expect(resolveChartProps({ chartType: 'donut', values: [1], labels: ['a'], legend: 'bottom' }).legend).toBe('bottom');
  });
  it('a plotted line takes its labels as its x axis; a marker keeps a numeric label', () => {
    expect(resolveChartProps({ chartType: 'line', values: [1, 2], labels: ['Jan', 'Feb'] }).axisLabels).toEqual(['Jan', 'Feb']);
    expect(resolveChartProps({ chartType: 'bar', values: [1, 2], labels: ['Jan', 'Feb'] }).axisLabels).toEqual([]);
    expect(resolveChartProps({ values: [1], marker: { index: 0, label: 12 } }).marker).toEqual({ index: 0, label: '12' });
    expect(resolveChartProps({ values: [1], marker: { index: 0, label: {} } }).marker).toEqual({ index: 0, label: '' });
    expect(resolveChartProps({ values: [1], marker: { label: 'x' } }).marker).toBeNull();
  });
  it('bound values replace the design\'s sample values', () => {
    expect(resolveChartProps({ values: [9, 9] }, [1, 2, 3]).values).toEqual([1, 2, 3]);
    expect(resolveChartProps({ values: [9, 9] }, []).values).toEqual([9, 9]);
  });
});

describe('bar geometry', () => {
  it('a bar path rounds its top corners, never past half its width', () => {
    expect(barPath(0, 0, 0, 10, 4)).toBe('');
    expect(barPath(0, 0, 10, 20, 0)).toContain(' Z');
    expect(barPath(0, 0, 10, 20, 50)).toContain('A');
  });
});

describe('donut geometry', () => {
  it('one arc per positive value, each its share of the ring', () => {
    const arcs = donutArcs([3, 0, 1, -2], 100, 0.6, 0, 2);
    expect(arcs.map((a) => [a.index, a.fraction])).toEqual([[0, 0.75], [2, 0.25]]);
    expect(arcs.every((a) => a.d.startsWith('M '))).toBe(true);
  });
  it('a pie fills to the centre; nothing positive is no ring; one value is a whole ring', () => {
    expect(donutArcs([1, 1], 80, 0, 90, 0)[0]!.d.startsWith('M 40 40')).toBe(true);
    expect(donutArcs([0, -1], 80, 0.5, 0, 2)).toEqual([]);
    expect(donutArcs([5], 80, 0.5, 0, 10)).toHaveLength(1);
  });
});

describe('every chart kind, drawn', () => {
  const sizes = { width: 320, height: 180 };
  it('a donut with its legend placed every way, its centre figure and colours', () => {
    for (const legend of ['right', 'bottom', 'none']) {
      const json = draw(
        <Chart {...sizes} chartType="donut" values={[40, 35, 25]} labels={['Rent', 'Food', 'Travel']} legend={legend}
          colors={['#111', '#222']} centerLabel="Total" centerValue="AED 12,345.00" centerColor="#333" segmentGap={3} startAngle={-90} />,
      );
      expect(json).not.toBe('null');
    }
    expect(draw(<Chart {...sizes} chartType="pie" values={[1, 2]} labels={['a', 'b']} trackColor="#eee" />)).not.toBe('null');
    expect(draw(<Chart {...sizes} chartType="donut" values={[]} />)).not.toBe('null');
  });
  it('a line and an area, smooth or not, with dots, a grid, an axis, a marker and several series', () => {
    for (const chartType of ['line', 'area']) {
      for (const smooth of [true, false]) {
        const json = draw(
          <Chart {...sizes} chartType={chartType} smooth={smooth} dots gridLines={3} gridColor="#ddd"
            values={[3, 7, 2, 9]} labels={['Jan', 'Feb', 'Mar', 'Apr']} axisColor="#999"
            marker={{ index: 2, label: '2 Mar' }} strokeColor="#06f" strokeWidth={3}
            series={[{ values: [3, 7, 2, 9] }, { values: [1, 2, 3, 4], color: '#f60' }]} />,
        );
        expect(json).toContain('Jan');
      }
    }
    expect(draw(<Chart {...sizes} chartType="line" values={[5]} />)).not.toBe('null');
  });
  it('no room is no chart', () => {
    expect(draw(<Chart width={0} height={100} values={[1]} />)).toBe('null');
  });
});
